/// A cell or array whose region nothing named, and so was taken as
/// `acyclic`: FX-26's is a fresh region, KFX's would be no region, its
/// effects lost.
pub fn unplaced_p(t: &'static Ty) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyRef(e, r) => {
            let tagcase_ = r;
            match *tagcase_ {
                Ty::TyRconst(n) => {
                    string_eq_p(n, str_lit("acyclic"))
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyFlat(e, r) => {
            let tagcase_ = r;
            match *tagcase_ {
                Ty::TyRconst(n) => {
                    string_eq_p(n, str_lit("acyclic"))
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        Ty::TyTag(a, h, d, r) => {
            let tagcase_ = r;
            match *tagcase_ {
                Ty::TyRconst(n) => {
                    (string_eq_p(n, str_lit("acyclic")) || string_eq_p(n, str_lit("%fresh")))
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

