/// The moduleof a module type names, as a list of one; or none.
pub fn module_spec(v: &'static Cv, t: &'static Ty) -> Sexps {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyData(d, args) => {
            if has_prefix_p(d, str_lit("%module ")) {
                let found = find_alias(after_prefix(d, str_lit("%module ")), cv_aliases(v));
                if null_p(found) {
                    nil()
                } else {
                    let tagcase_ = car(found);
                    match *tagcase_ {
                        Alias::Alias(n, ps, body) => {
                            the::<Sexps>(cons(body, nil()))
                        }
                    }
                }
            } else {
                nil()
            }
        }
        _ => {
            let other = tagcase_;
            nil()
        }
    }
}

pub fn fold_values(v: &'static Cv, s: &'static St, m: Str, bs: Binds) -> &'static St {
    if null_p(bs) {
        s
    } else {
        let tagcase_ = car(bs);
        match *tagcase_ {
            Bind::Bind(n, sc, w) => {
                let found = find_bind(string_append(m, string_append(str_lit(" "), n)), cv_binds(v));
                if null_p(found) {
                    refuse(v, string_append(m, string_append(str_lit(" gives no value "), n)))
                } else {
                    let tagcase_ = car(found);
                    match *tagcase_ {
                        Bind::Bind(n2, sc2, w2) => {
                            let tagcase_ = instantiate(s, sc2);
                            match *tagcase_ {
                                Inst::Inst(t, s, regions) => {
                                    let tagcase_ = sc;
                                    match *tagcase_ {
                                        Scheme::Scheme(tv, want) => {
                                            fold_values(v, fits(v, s, t, want), m, cdr(bs))
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

/// That the module `m`, defined at the top level, is a `x`: a type for each
/// abstract one, the same type for each description, and each value, of a
/// type that fits. The emitter is told, to write the trait's impl.
pub fn conforms(v: &'static Cv, s: &'static St, m: Str, x: Str, spec: &'static Sexp) -> &'static St {
    let w = module_scope(v, spec, str_lit(""), m);
    map(lambda1(move |t: Str| {
        if null_p(find_alias(string_append(m, string_append(str_lit(" "), t)), cv_aliases(v))) {
            refuse(v, string_append(m, string_append(str_lit(" gives no type "), t)))
        } else {
            ()
        }
    }), spec_abs(spec));
    map(lambda1(move |d: Sexps| {
        let mine = string_append(m, string_append(str_lit(" "), sym_name(second(d))));
        if null_p(find_alias(mine, cv_aliases(v))) {
            refuse(v, string_append(m, string_append(str_lit(" gives no type "), sym_name(second(d)))))
        } else {
            let (a, b) = (parse_type(v, nil(), sym(mine)), parse_type(w, nil(), third(d)));
            fits(v, fits(v, s, a, b), b, a);
            ()
        }
    }), spec_items(spec, str_lit("desc")));
    note_fact(fold_values(v, s, m, module_type_values(w, spec)), str_lit(""), 0i64, string_append(str_lit("module-impl "), string_append(m, string_append(str_lit(" "), x))))
}

/// Whether the lambda checked is a top-level definition's, as a procedure of
/// a module parameter must be (C24).
pub fn top_lambda_p(v: &'static Cv) -> bool {
    let found = find_bind(str_lit("%toplambda"), cv_binds(v));
    (not(null_p(found)) && {
        let tagcase_ = car(found);
        match *tagcase_ {
            Bind::Bind(n, sc, w) => {
                string_eq_p(w, str_lit("yes"))
            }
        }
    })
}

/// Whether `t` mentions a type or region variable.
pub fn has_var_p(s: &'static St, t: &'static Ty) -> bool {
    let tagcase_ = walk(s, t);
    match *tagcase_ {
        Ty::TyVar(n) => {
            true
        }
        Ty::TyList(e, r) => {
            (has_var_p(s, e) || has_var_p(s, r))
        }
        Ty::TyFlat(e, r) => {
            (has_var_p(s, e) || has_var_p(s, r))
        }
        Ty::TyRef(e, r) => {
            (has_var_p(s, e) || has_var_p(s, r))
        }
        Ty::TyTag(a, h, d, r) => {
            (has_var_p(s, a) || has_var_p(s, h) || has_var_p(s, r))
        }
        Ty::TyData(d, args) => {
            any_p(lambda1(move |x: &'static Ty| {
                has_var_p(s, x)
            }), args)
        }
        Ty::TyShape(p, ls, ts) => {
            any_p(lambda1(move |x: &'static Ty| {
                has_var_p(s, x)
            }), ts)
        }
        Ty::TyProc(es, ps, r) => {
            (has_var_p(s, r) || any_p(lambda1(move |x: &'static Ty| {
                has_var_p(s, x)
            }), ps))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// A procedure named as an argument that cannot abort, given for a
/// parameter that may: its Rust type returns no `Result`, so the emitter
/// wraps it in a closure that returns `Ok` (`lift-arg I N`, N its arity).
pub fn lifted_args(mut v: &'static Cv, mut s: &'static St, mut args: Sexps, mut ps: Tys, mut i: i64) -> &'static St {
    loop {
        if (null_p(args) || null_p(ps)) {
            return s;
        } else {
            (s, args, ps, i) = ({
                let tagcase_ = car(args);
                match *tagcase_ {
                    Sexp::Sym(n) => {
                        let found = find_bind(n, cv_binds(v));
                        if null_p(found) {
                            s
                        } else {
                            let tagcase_ = car(found);
                            match *tagcase_ {
                                Bind::Bind(x, sc, w) => {
                                    let tagcase_ = sc;
                                    match *tagcase_ {
                                        Scheme::Scheme(tv, t) => {
                                            let tagcase_ = walk(s, t);
                                            match *tagcase_ {
                                                Ty::TyProc(es, xs, r) => {
                                                    let tagcase_ = walk(s, car(ps));
                                                    match *tagcase_ {
                                                        Ty::TyProc(ees, eps, er) => {
                                                            if (escapes_p(ees) && not(escapes_p(es))) {
                                                                note_fact(s, cv_file(v), cv_pos(v), string_append(str_lit("lift-arg "), string_append(i64_to_string(i), string_append(str_lit(" "), i64_to_string(size(xs))))))
                                                            } else {
                                                                s
                                                            }
                                                        }
                                                        _ => {
                                                            let other = tagcase_;
                                                            s
                                                        }
                                                    }
                                                }
                                                _ => {
                                                    let other = tagcase_;
                                                    s
                                                }
                                            }
                                        }
                                    }
                                }
                            }
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        s
                    }
                }
            }, cdr(args), cdr(ps), i64_plus(i, 1i64));
            continue;
        }
    }
}

/// `s`, a list's region in `t` that nothing solved made fresh, as FX-26
/// makes it where it finds a value by itself.
pub fn freshened(mut s: &'static St, mut t: &'static Ty) -> &'static St {
    loop {
        let tagcase_ = walk(s, t);
        match *tagcase_ {
            Ty::TyList(e, r) => {
                let s = freshened(s, e);
                let tagcase_ = walk(s, r);
                match *tagcase_ {
                    Ty::TyMeta(k) => {
                        return solve(s, k, ty_rconst(str_lit("%fresh")));
                    }
                    _ => {
                        let other = tagcase_;
                        return s;
                    }
                }
            }
            Ty::TyProc(es, ps, r) => {
                t = r;
                continue;
            }
            _ => {
                let other = tagcase_;
                return s;
            }
        }
    }
}

pub fn control_form_p(h: Str) -> bool {
    (string_eq_p(h, str_lit("if")) || string_eq_p(h, str_lit("cond")) || string_eq_p(h, str_lit("case")) || string_eq_p(h, str_lit("tagcase")) || string_eq_p(h, str_lit("let")) || string_eq_p(h, str_lit("let*")) || string_eq_p(h, str_lit("begin")) || string_eq_p(h, str_lit("letrec")) || string_eq_p(h, str_lit("letregion")) || string_eq_p(h, str_lit("with")))
}

/// The inference variables in `t` as it stands, solved or not.
pub fn metas_of(t: &'static Ty) -> I64s {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyMeta(k) => {
            the::<I64s>(cons(k, nil()))
        }
        Ty::TyList(e, r) => {
            onto(metas_of(e), metas_of(r))
        }
        Ty::TyFlat(e, r) => {
            onto(metas_of(e), metas_of(r))
        }
        Ty::TyRef(e, r) => {
            onto(metas_of(e), metas_of(r))
        }
        Ty::TyTag(a, h, d, r) => {
            onto(metas_of(a), onto(metas_of(h), metas_of(r)))
        }
        Ty::TyData(d, args) => {
            concat(map(&metas_of, args))
        }
        Ty::TyShape(p, ls, ts) => {
            concat(map(&metas_of, ts))
        }
        Ty::TyProc(es, ps, r) => {
            onto(metas_of(r), concat(map(&metas_of, ps)))
        }
        _ => {
            let other = tagcase_;
            nil()
        }
    }
}

/// Of `ks`, those that fitting the result expected solved.
pub fn fixed_by(before: &'static St, after: &'static St, ks: I64s) -> I64s {
    concat(map(lambda1(move |k: i64| {
        if ({
            let tagcase_ = walk(before, ty_meta(k));
            match *tagcase_ {
                Ty::TyMeta(j) => {
                    true
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        } && {
            let tagcase_ = walk(after, ty_meta(k));
            match *tagcase_ {
                Ty::TyMeta(j) => {
                    false
                }
                _ => {
                    let other = tagcase_;
                    true
                }
            }
        }) {
            the::<I64s>(cons(k, nil()))
        } else {
            nil()
        }
    }), ks))
}

/// Whether `t` has an inference variable in it, solved or not: a
/// parameter's type that is an instance's.
pub fn raw_meta_p(t: &'static Ty) -> bool {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyMeta(k) => {
            true
        }
        Ty::TyList(e, r) => {
            (raw_meta_p(e) || raw_meta_p(r))
        }
        Ty::TyFlat(e, r) => {
            (raw_meta_p(e) || raw_meta_p(r))
        }
        Ty::TyRef(e, r) => {
            (raw_meta_p(e) || raw_meta_p(r))
        }
        Ty::TyTag(a, h, d, r) => {
            (raw_meta_p(a) || raw_meta_p(h) || raw_meta_p(r))
        }
        Ty::TyData(d, args) => {
            any_p(&raw_meta_p, args)
        }
        Ty::TyShape(p, ls, ts) => {
            any_p(&raw_meta_p, ts)
        }
        Ty::TyProc(es, ps, r) => {
            (raw_meta_p(r) || any_p(&raw_meta_p, ps))
        }
        _ => {
            let other = tagcase_;
            false
        }
    }
}

/// Module `m`'s types, named as `m` names them.
pub fn opened_aliases(mut m: Str, mut r#as: Aliases) -> Aliases {
    loop {
        if null_p(r#as) {
            return nil();
        } else {
            let tagcase_ = car(r#as);
            match *tagcase_ {
                Alias::Alias(n, ps, body) => {
                    if has_prefix_p(n, string_append(m, str_lit(" "))) {
                        return cons(alias(after_prefix(n, string_append(m, str_lit(" "))), ps, body), opened_aliases(m, cdr(r#as)));
                    } else {
                        r#as = cdr(r#as);
                        continue;
                    }
                }
            }
        }
    }
}

/// `v`, in a `(with m ...)`: `m`'s values, types and effects.
pub fn opened(v: &'static Cv, m: Str) -> &'static Cv {
    let tagcase_ = v;
    match *tagcase_ {
        Cv::Cv(bs, ds, r#as, es, here, group, file, line, fs, tv, at) => {
            cv(bind_onto(opened_binds(m, bs), bs), ds, onto(opened_aliases(m, r#as), r#as), onto(concat(map(lambda1(move |d: &'static Effdef| {
                let tagcase_ = d;
                match *tagcase_ {
                    Effdef::Effdef(n, atoms) => {
                        if has_prefix_p(n, string_append(m, str_lit(" "))) {
                            the::<Effdefs>(cons(effdef(after_prefix(n, string_append(m, str_lit(" "))), atoms), nil()))
                        } else {
                            nil()
                        }
                    }
                }
            }), es)), es), here, group, file, line, fs, tv, at)
        }
    }
}

/// Whether `xs` are literals a case on a `kind` compares with.
pub fn case_data_p(kind: Str, xs: Sexps) -> bool {
    not(any_p(lambda1(move |x: &'static Sexp| {
        not({
            let tagcase_ = x;
            match *tagcase_ {
                Sexp::Chr(c) => {
                    string_eq_p(kind, str_lit("char"))
                }
                Sexp::Num(k, text, pos) => {
                    string_eq_p(kind, str_lit("int"))
                }
                Sexp::Big(text, f, p) => {
                    string_eq_p(kind, str_lit("int"))
                }
                Sexp::Str(t) => {
                    string_eq_p(kind, str_lit("string"))
                }
                Sexp::Sym(n) => {
                    (string_eq_p(kind, str_lit("bool")) && (string_eq_p(n, str_lit("#t")) || string_eq_p(n, str_lit("#f"))))
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        })
    }), xs))
}

/// A big literal's sign and digits, its leading zeros dropped.
pub fn big_digits(mut cs: Chars) -> Chars {
    loop {
        if null_p(cs) {
            return nil();
        } else if char_eq_p(car(cs), '-') {
            return cons('-', big_digits(cdr(cs)));
        } else if (char_eq_p(car(cs), '0') && not(null_p(cdr(cs)))) {
            cs = cdr(cs);
            continue;
        } else {
            return cs;
        }
    }
}

/// A case datum, as a key that two data equal share.
pub fn datum_key(d: &'static Sexp) -> Str {
    let tagcase_ = d;
    match *tagcase_ {
        Sexp::Chr(c) => {
            string_append(str_lit("c"), char_to_string(c))
        }
        Sexp::Num(k, f, p) => {
            string_append(str_lit("n"), i64_to_string(k))
        }
        Sexp::Big(text, f, p) => {
            string_append(str_lit("b"), list_to_string(big_digits(string_chars(text))))
        }
        Sexp::Str(x) => {
            string_append(str_lit("s"), x)
        }
        Sexp::Sym(n) => {
            string_append(str_lit("y"), n)
        }
        _ => {
            let other = tagcase_;
            str_lit("?")
        }
    }
}

pub fn all_chars_p(xs: Sexps) -> bool {
    not(any_p(lambda1(move |x: &'static Sexp| {
        let tagcase_ = x;
        match *tagcase_ {
            Sexp::Chr(c) => {
                false
            }
            _ => {
                let other = tagcase_;
                true
            }
        }
    }), xs))
}

pub fn bind_fields(v: &'static Cv, names: Sexps, types: Tys) -> Binds {
    if null_p(names) {
        nil()
    } else {
        cons(local(v, name_of(v, car(names)), car(types)), bind_fields(v, cdr(names), cdr(types)))
    }
}

pub fn bind_params(v: &'static Cv, params: Sexps, types: Tys) -> Binds {
    if null_p(params) {
        nil()
    } else {
        cons(local(v, param_name(car(params)), car(types)), bind_params(v, cdr(params), cdr(types)))
    }
}

pub fn find_dt(mut d: Str, mut ds: Dts) -> List<Variants> {
    loop {
        if null_p(ds) {
            return nil();
        } else {
            let tagcase_ = car(ds);
            match *tagcase_ {
                Dt::Dt(n, ps, vs) => {
                    if string_eq_p(n, d) {
                        return cons(vs, nil());
                    } else {
                        ds = cdr(ds);
                        continue;
                    }
                }
            }
        }
    }
}

/// A datatype's parameters.
pub fn family_of(v: &'static Cv, d: Str) -> Strings {
    let found = find_family(d, cv_dts(v));
    if null_p(found) {
        nil()
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Dt::Dt(n, ps, vs) => {
                ps
            }
        }
    }
}

/// Variants whose fields' types are of the datatype's parameters, at
/// `args`.
pub fn instantiate_variants(params: Strings, args: Tys, vs: Variants) -> Variants {
    map(lambda1(move |x: &'static Variant| {
        let tagcase_ = x;
        match *tagcase_ {
            Variant::Variant(tag, fields) => {
                variant(tag, map(lambda1(move |f: &'static Ty| {
                    substitute(params, args, f)
                }), fields))
            }
        }
    }), vs)
}

pub fn variants_of(v: &'static Cv, d: Str) -> Variants {
    let found = find_dt(d, cv_dts(v));
    if null_p(found) {
        refuse(v, string_append(str_lit("no datatype is named "), d))
    } else {
        car(found)
    }
}

pub fn variant_fields(mut v: &'static Cv, mut d: Str, mut tag: Str, mut vs: Variants) -> Tys {
    loop {
        if null_p(vs) {
            return refuse(v, string_append(tag, string_append(str_lit(" is no tag of "), string_append(d, str_lit(", or has an arm already")))));
        } else {
            let tagcase_ = car(vs);
            match *tagcase_ {
                Variant::Variant(t, fields) => {
                    if string_eq_p(t, tag) {
                        return fields;
                    } else {
                        vs = cdr(vs);
                        continue;
                    }
                }
            }
        }
    }
}

pub fn without_tag(tag: Str, vs: Variants) -> Variants {
    if null_p(vs) {
        nil()
    } else {
        let tagcase_ = car(vs);
        match *tagcase_ {
            Variant::Variant(t, fields) => {
                if string_eq_p(t, tag) {
                    cdr(vs)
                } else {
                    cons(car(vs), without_tag(tag, cdr(vs)))
                }
            }
        }
    }
}

pub fn synth(v: &'static Cv, s: &'static St, e: &'static Sexp) -> &'static Res {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Num(k, num_file, num_pos) => {
            res(ty_int(), nil(), note_fact(s, num_file, num_pos, str_lit("int")))
        }
        Sexp::Big(text, f, p) => {
            res(ty_int(), nil(), s)
        }
        Sexp::Chr(c) => {
            res(ty_char(), nil(), s)
        }
        Sexp::Real(x) => {
            res(ty_f64(), nil(), s)
        }
        Sexp::Str(x) => {
            res(ty_string(), nil(), s)
        }
        Sexp::Sym(name) => {
            synth_name(v, s, name)
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            let v = near(v, src_file, src_line, src_pos);
            let tagcase_ = car(xs);
            match *tagcase_ {
                Sexp::Sym(h) => {
                    synth_form(v, s, e, h, cdr(xs))
                }
                _ => {
                    let head = tagcase_;
                    synth_call_of(v, s, synth(v, s, head), cdr(xs), nil(), nil(), cons(str_lit("spin"), nil()))
                }
            }
        }
    }
}

pub fn synth_name(v: &'static Cv, s: &'static St, name: Str) -> &'static Res {
    if (string_eq_p(name, str_lit("#t")) || string_eq_p(name, str_lit("#f"))) {
        res(ty_bool(), nil(), s)
    } else if string_eq_p(name, str_lit("#u")) {
        res(ty_unit(), nil(), s)
    } else {
        let found = find_bind(name, cv_binds(v));
        if null_p(found) {
            refuse(v, string_append(str_lit("nothing is named "), name))
        } else {
            let tagcase_ = car(found);
            match *tagcase_ {
                Bind::Bind(n, sc, r#where) => {
                    if (string_eq_p(r#where, str_lit("module")) || not(null_p(module_spec(v, {
                        let tagcase_ = sc;
                        match *tagcase_ {
                            Scheme::Scheme(tv, t) => {
                                t
                            }
                        }
                    })))) {
                        refuse(v, string_append(str_lit("a module as a value: KFX's modules are Rust's, opened by with: "), name))
                    } else if {
                        let tagcase_ = sc;
                        match *tagcase_ {
                            Scheme::Scheme(tv, t) => {
                                let tagcase_ = t;
                                match *tagcase_ {
                                    Ty::TyProc(es, ps, r) => {
                                        any_p(lambda1(move |p: &'static Ty| {
                                            not(null_p(module_spec(v, p)))
                                        }), ps)
                                    }
                                    _ => {
                                        let other = tagcase_;
                                        false
                                    }
                                }
                            }
                        }
                    } {
                        refuse(v, string_append(str_lit("a procedure of a module parameter, a Rust generic fn, named as a value: "), name))
                    } else {
                        let tagcase_ = instantiate(s, sc);
                        match *tagcase_ {
                            Inst::Inst(t, s, regions) => {
                                res(t, naming_effs(s, name, r#where, t, cv_group(v)), s)
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn check(v: &'static Cv, s: &'static St, e: &'static Sexp, expected: &'static Ty) -> &'static Res {
    let x = walk(s, expected);
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Num(k, num_file, num_pos) => {
            // A literal is an `i64` where one is expected, and otherwise an
            // `int`, as in FX-26: an inference variable it meets is solved
            // to `int`.
            let tagcase_ = x;
            match *tagcase_ {
                Ty::TyI64() => {
                    res(x, nil(), s)
                }
                Ty::TyInt() => {
                    res(x, nil(), note_fact(s, num_file, num_pos, str_lit("int")))
                }
                Ty::TyNat() => {
                    if (i64_lt(k, 0i64) || i64_gt(k, 1152921504606846975i64)) {
                        refuse(v, string_append(i64_to_string(k), str_lit(" is no nat: FX-26's nat literals are below 2^60")))
                    } else {
                        res(x, nil(), note_fact(s, num_file, num_pos, str_lit("int")))
                    }
                }
                Ty::TyMeta(m) => {
                    res(ty_int(), nil(), note_fact(solve(s, m, ty_int()), num_file, num_pos, str_lit("int")))
                }
                Ty::TyData(d, args) => {
                    if (string_eq_p(d, str_lit("i32")) && not(i64_lt(k, -2147483648i64)) && not(i64_gt(k, 2147483647i64))) {
                        res(x, nil(), note_fact(s, num_file, num_pos, str_lit("fixed i32")))
                    } else if (string_eq_p(d, str_lit("u32")) && not(i64_lt(k, 0i64)) && not(i64_gt(k, 4294967295i64))) {
                        res(x, nil(), note_fact(s, num_file, num_pos, str_lit("fixed u32")))
                    } else if (string_eq_p(d, str_lit("u64")) && not(i64_lt(k, 0i64))) {
                        res(x, nil(), note_fact(s, num_file, num_pos, str_lit("fixed u64")))
                    } else if fixed_width_p(d) {
                        refuse(v, string_append(i64_to_string(k), string_append(str_lit(" is not a "), d)))
                    } else {
                        refuse(v, string_append(str_lit("a literal is here, where a "), string_append(show_ty(s, x), str_lit(" is expected"))))
                    }
                }
                _ => {
                    let other = tagcase_;
                    refuse(v, string_append(str_lit("a literal is here, where a "), string_append(show_ty(s, x), str_lit(" is expected"))))
                }
            }
        }
        Sexp::Big(text, f, p) => {
            // A literal past an i64: an `int`, or a `nat` if not negative.
            let tagcase_ = x;
            match *tagcase_ {
                Ty::TyInt() => {
                    res(x, nil(), s)
                }
                Ty::TyNat() => {
                    refuse(v, string_append(text, str_lit(" is no nat: FX-26's nat literals are below 2^60")))
                }
                Ty::TyMeta(m) => {
                    res(ty_int(), nil(), solve(s, m, ty_int()))
                }
                Ty::TyData(d, args) => {
                    if (string_eq_p(d, str_lit("u64")) && not(char_eq_p(string_ref_i64(text, 0i64), '-')) && (i64_lt(string_length_i64(text), 20i64) || (i64_eq(string_length_i64(text), 20i64) && digits_at_most_p(string_chars(text), string_chars(str_lit("18446744073709551615")))))) {
                        res(x, nil(), note_fact(s, f, p, str_lit("fixed u64")))
                    } else {
                        refuse(v, string_append(text, string_append(str_lit(" is not a "), d)))
                    }
                }
                _ => {
                    let other = tagcase_;
                    refuse(v, string_append(str_lit("a literal past an i64 is here, where a "), string_append(show_ty(s, x), str_lit(" is expected"))))
                }
            }
        }
        Sexp::Lst(xs, src_file, src_line, src_pos) => {
            let v = near(v, src_file, src_line, src_pos);
            let tagcase_ = car(xs);
            match *tagcase_ {
                Sexp::Sym(h) => {
                    check_form(v, s, e, h, cdr(xs), x)
                }
                _ => {
                    let other = tagcase_;
                    check_by_synth(v, s, e, x)
                }
            }
        }
        Sexp::Sym(name) => {
            if string_eq_p(name, str_lit("nil")) {
                let tagcase_ = x;
                match *tagcase_ {
                    Ty::TyList(el, r) => {
                        res(x, nil(), s)
                    }
                    _ => {
                        let other = tagcase_;
                        check_by_synth(v, s, e, x)
                    }
                }
            } else {
                check_by_synth(v, s, e, x)
            }
        }
        _ => {
            let other = tagcase_;
            check_by_synth(v, s, e, x)
        }
    }
}

pub fn check_by_synth(v: &'static Cv, s: &'static St, e: &'static Sexp, expected: &'static Ty) -> &'static Res {
    let tagcase_ = synth(v, s, e);
    match *tagcase_ {
        Res::Res(t, es, s) => {
            res(expected, es, fits(v, s, t, expected))
        }
    }
}

/// A body: each expression but the last for its effect, the last
/// checked against `expected` if it has one type in it, else found.
pub fn body(v: &'static Cv, s: &'static St, es: Sexps, expected: Tys) -> &'static Res {
    if null_p(cdr(es)) {
        if null_p(expected) {
            synth(v, s, car(es))
        } else {
            check(v, s, car(es), car(expected))
        }
    } else {
        let tagcase_ = synth_any(v, s, car(es));
        match *tagcase_ {
            Res::Res(t, es0, s) => {
                with_effs(body(v, s, cdr(es), expected), es0)
            }
        }
    }
}

/// An expression whose value is dropped: a string is a comment.
pub fn synth_any(v: &'static Cv, s: &'static St, e: &'static Sexp) -> &'static Res {
    let tagcase_ = e;
    match *tagcase_ {
        Sexp::Str(x) => {
            res(ty_unit(), nil(), s)
        }
        _ => {
            let other = tagcase_;
            synth(v, s, e)
        }
    }
}

pub fn synth_form(v: &'static Cv, s: &'static St, e: &'static Sexp, h: Str, xs: Sexps) -> &'static Res {
    if string_eq_p(h, str_lit("the")) {
        check(v, s, second(xs), parse_type(v, cv_tvars(v), car(xs)))
    } else if string_eq_p(h, str_lit("prompt")) {
        prompt_form(v, s, xs, nil())
    } else if string_eq_p(h, str_lit("%found")) {
        // A definition's value in a module that includes another: found by
        // itself, through a `the` too, as FX-26 finds it.
        let x = car(xs);
        if {
            let tagcase_ = x;
            match *tagcase_ {
                Sexp::Sym(n) => {
                    string_eq_p(n, str_lit("nil"))
                }
                _ => {
                    let other = tagcase_;
                    false
                }
            }
        } {
            refuse(v, str_lit("a nil, in a module that includes another, where FX-26 finds a poly list"))
        } else if head_is_p(x, str_lit("the")) {
            let tagcase_ = synth(v, s, lst(cons(sym(str_lit("%found")), cons(third(items(x)), nil())), str_lit(""), 0i64, 0i64));
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    let want = parse_type(v, cv_tvars(v), second(items(x)));
                    res(want, es, fits(v, s, t, want))
                }
            }
        } else {
            let tagcase_ = synth(v, s, x);
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    res(t, es, freshened(s, t))
                }
            }
        }
    } else if string_eq_p(h, str_lit("product")) {
        product_form(v, s, xs, nil())
    } else if string_eq_p(h, str_lit("sum")) {
        refuse(v, str_lit("a sum whose type is not known here: write it, (the (sumof ...) (sum ...))"))
    } else if string_eq_p(h, str_lit("extract")) {
        if not(i64_eq(size(xs), 2i64)) {
            refuse(v, str_lit("(extract e label)"))
        } else {
            let tagcase_ = synth(v, s, car(xs));
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    let tagcase_ = walk(s, t);
                    match *tagcase_ {
                        Ty::TyShape(p, ls, ts) => {
                            if (p && string_member_p(label_of(second(xs)), ls)) {
                                res(member_type(label_of(second(xs)), ls, ts), es, note_fact(s, cv_file(v), cv_pos(v), string_append(str_lit("extract-index "), i64_to_string(index_of(label_of(second(xs)), ls, 0i64)))))
                            } else {
                                refuse(v, string_append(str_lit("no field "), string_append(label_of(second(xs)), string_append(str_lit(" in a "), show_ty(s, t)))))
                            }
                        }
                        _ => {
                            let other = tagcase_;
                            refuse(v, string_append(str_lit("an extract from a "), string_append(show_ty(s, t), str_lit(", no product"))))
                        }
                    }
                }
            }
        }
    } else if string_eq_p(h, str_lit("lambda")) {
        synth_lambda(v, s, items(car(xs)), cdr(xs))
    } else if string_eq_p(h, str_lit("list")) {
        if null_p(xs) {
            let tagcase_ = fresh(s);
            match *tagcase_ {
                Res::Res(m, es, s) => {
                    res(ty_list(m, ty_rconst(str_lit("%fresh"))), nil(), s)
                }
            }
        } else {
            let tagcase_ = synth(v, s, car(xs));
            match *tagcase_ {
                Res::Res(t, es0, s) => {
                    // Its first element's type, a `nat`'s an `int`: FX-26's is that
                    // element's own `(nat v)`, which no other `nat` is.
                    if ({
                        let tagcase_ = walk(s, t);
                        match *tagcase_ {
                            Ty::TyNat() => {
                                true
                            }
                            _ => {
                                let other = tagcase_;
                                false
                            }
                        }
                    } && not(null_p(cdr(xs)))) {
                        refuse(v, str_lit("a list of nats: FX-26 types each its own (nat v), so no two share a list"))
                    } else {
                        let t = {
                            let tagcase_ = walk(s, t);
                            match *tagcase_ {
                                Ty::TyNat() => {
                                    ty_int()
                                }
                                _ => {
                                    let other = tagcase_;
                                    t
                                }
                            }
                        };
                        with_effs(check(v, s, e, ty_list(t, ty_rconst(str_lit("%fresh")))), es0)
                    }
                }
            }
        }
    } else if control_form_p(h) {
        body_form(v, s, h, xs, nil())
    } else if string_eq_p(h, str_lit("and")) {
        bools(v, s, xs)
    } else if string_eq_p(h, str_lit("or")) {
        bools(v, s, xs)
    } else {
        synth_call(v, s, h, xs, nil())
    }
}

pub fn check_form(v: &'static Cv, s: &'static St, e: &'static Sexp, h: Str, xs: Sexps, expected: &'static Ty) -> &'static Res {
    if control_form_p(h) {
        body_form(v, s, h, xs, cons(expected, nil()))
    } else if string_eq_p(h, str_lit("prompt")) {
        prompt_form(v, s, xs, cons(expected, nil()))
    } else if string_eq_p(h, str_lit("%found")) {
        check_by_synth(v, s, e, expected)
    } else if string_eq_p(h, str_lit("product")) {
        product_form(v, s, xs, cons(expected, nil()))
    } else if string_eq_p(h, str_lit("sum")) {
        sum_form(v, s, xs, expected)
    } else if (string_eq_p(h, str_lit("lambda")) && proc_type_p(s, expected)) {
        check_lambda(v, s, items(car(xs)), cdr(xs), walk(s, expected))
    } else if (string_eq_p(h, str_lit("list")) && {
        let tagcase_ = expected;
        match *tagcase_ {
            Ty::TyList(el, r) => {
                true
            }
            _ => {
                let other = tagcase_;
                false
            }
        }
    }) {
        let tagcase_ = expected;
        match *tagcase_ {
            Ty::TyList(el, r) => {
                let tagcase_ = elements(v, s, xs, el);
                match *tagcase_ {
                    Res::Res(u, es, s) => {
                        let tagcase_ = region_of(v, s, r);
                        match *tagcase_ {
                            Res::Res(rr, rn, s) => {
                                res(expected, effs_union(cons(string_append(str_lit("alloc:"), region_string(s, rr)), nil()), es), s)
                            }
                        }
                    }
                }
            }
            _ => {
                let other = tagcase_;
                check_by_synth(v, s, e, expected)
            }
        }
    } else if (string_eq_p(h, str_lit("the")) || string_eq_p(h, str_lit("and")) || string_eq_p(h, str_lit("or")) || string_eq_p(h, str_lit("lambda")) || string_eq_p(h, str_lit("list")) || string_eq_p(h, str_lit("extract"))) {
        check_by_synth(v, s, e, expected)
    } else {
        synth_call(v, s, h, xs, cons(expected, nil()))
    }
}

/// A list's elements, each checked as `el`: their effect, and the state,
/// which carries their facts.
pub fn elements(v: &'static Cv, s: &'static St, xs: Sexps, el: &'static Ty) -> &'static Res {
    if null_p(xs) {
        res(el, nil(), s)
    } else {
        let tagcase_ = check(v, s, car(xs), el);
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(elements(v, s, cdr(xs), el), es)
            }
        }
    }
}

pub fn bools(v: &'static Cv, s: &'static St, xs: Sexps) -> &'static Res {
    if null_p(xs) {
        res(ty_bool(), nil(), s)
    } else {
        let tagcase_ = check(v, s, car(xs), ty_bool());
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(bools(v, s, cdr(xs)), es)
            }
        }
    }
}

/// `if`, `cond`, `case`, `tagcase`, `let`, `let*` and `begin`: forms
/// whose last parts give the value; `expected` is the type, if known.
pub fn body_form(v: &'static Cv, s: &'static St, h: Str, xs: Sexps, expected: Tys) -> &'static Res {
    if not(well_formed_p(h, xs)) {
        refuse(v, string_append(str_lit("a ("), string_append(h, str_lit(" ...) not of the form FX-26 has"))))
    } else if string_eq_p(h, str_lit("if")) {
        let tagcase_ = check(v, s, car(xs), ty_bool());
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(arms(v, s, cdr(xs), expected), es)
            }
        }
    } else if string_eq_p(h, str_lit("begin")) {
        body(v, s, xs, expected)
    } else if string_eq_p(h, str_lit("let")) {
        let_values(v, s, items(car(xs)), cdr(xs), expected, nil(), false)
    } else if string_eq_p(h, str_lit("let*")) {
        let_values(v, s, items(car(xs)), cdr(xs), expected, nil(), true)
    } else if string_eq_p(h, str_lit("letrec")) {
        letrec_form(v, s, items(car(xs)), cdr(xs), expected)
    } else if string_eq_p(h, str_lit("letregion")) {
        letregion_form(v, s, name_of(v, car(xs)), cdr(xs), expected)
    } else if string_eq_p(h, str_lit("with")) {
        // `(with m body ...)`: `m`'s values and types in scope in the body,
        // shadowing what is outside, locals too, as FX-26 has it; `m` a
        // module defined at the top level, reading which is reading a
        // global.
        let m = name_of(v, car(xs));
        let found = find_bind(m, cv_binds(v));
        if (not(null_p(found)) && {
            let tagcase_ = car(found);
            match *tagcase_ {
                Bind::Bind(n, sc, r#where) => {
                    string_eq_p(r#where, str_lit("local"))
                }
            }
        } && not(null_p(module_spec(v, {
            let tagcase_ = car(found);
            match *tagcase_ {
                Bind::Bind(n, sc, r#where) => {
                    let tagcase_ = sc;
                    match *tagcase_ {
                        Scheme::Scheme(tv, t) => {
                            t
                        }
                    }
                }
            }
        })))) {
            // A module parameter's values, of its abstract types `m..t`.
            let spec = car(module_spec(v, {
                let tagcase_ = car(found);
                match *tagcase_ {
                    Bind::Bind(n, sc, r#where) => {
                        let tagcase_ = sc;
                        match *tagcase_ {
                            Scheme::Scheme(tv, t) => {
                                t
                            }
                        }
                    }
                }
            }));
            let w = module_scope(v, spec, m, str_lit(""));
            found_then_fitted(v, body(with_binds(w, module_type_values(w, spec)), s, cdr(xs), nil()), expected)
        } else if (null_p(found) || not({
            let tagcase_ = car(found);
            match *tagcase_ {
                Bind::Bind(n, sc, r#where) => {
                    string_eq_p(r#where, str_lit("module"))
                }
            }
        })) {
            refuse(v, string_append(str_lit("KFX's with opens a module defined at the top level, or a module parameter, by its name: "), m))
        } else {
            with_effs(found_then_fitted(v, body(opened(v, m), s, cdr(xs), nil()), expected), cons(string_append(str_lit("g:"), m), nil()))
        }
    } else if string_eq_p(h, str_lit("cond")) {
        cond_clauses(v, s, xs, expected)
    } else if string_eq_p(h, str_lit("case")) {
        // On a character, an integer, a string or a boolean, the data
        // literals of its type; the kind told the emitter.
        let tagcase_ = synth(v, s, car(xs));
        match *tagcase_ {
            Res::Res(t, es, s) => {
                let kind = {
                    let tagcase_ = walk(s, t);
                    match *tagcase_ {
                        Ty::TyChar() => {
                            str_lit("char")
                        }
                        Ty::TyInt() => {
                            str_lit("int")
                        }
                        Ty::TyNat() => {
                            str_lit("int")
                        }
                        Ty::TyString() => {
                            str_lit("string")
                        }
                        Ty::TyBool() => {
                            str_lit("bool")
                        }
                        _ => {
                            let other = tagcase_;
                            refuse(v, string_append(str_lit("KFX's case is on characters, ints, strings and booleans, and this is a "), show_ty(s, t)))
                        }
                    }
                };
                with_effs(case_arms(v, note_fact(s, cv_file(v), cv_pos(v), string_append(str_lit("case "), kind)), kind, cdr(xs), expected), es)
            }
        }
    } else {
        let tagcase_ = synth(v, s, car(xs));
        match *tagcase_ {
            Res::Res(t, es, s) => {
                let tagcase_ = walk(s, t);
                match *tagcase_ {
                    Ty::TyData(d, args) => {
                        if null_p(variants_of(v, d)) {
                            refuse(v, string_append(str_lit("tagcase of a "), string_append(show_ty(s, t), str_lit(", no sum"))))
                        } else {
                            with_effs(tag_arms(v, s, walk(s, t), cdr(xs), instantiate_variants(family_of(v, d), args, variants_of(v, d)), expected), es)
                        }
                    }
                    Ty::TyShape(p, ls, ts) => {
                        if p {
                            refuse(v, string_append(str_lit("tagcase of a "), string_append(show_ty(s, t), str_lit(", no sum"))))
                        } else {
                            let arms = cdr(xs);
                            with_effs(tag_arms(v, note_fact(s, cv_file(v), cv_pos(v), string_append(str_lit("tagcase-sum "), words_of(ls))), walk(s, t), map(&sum_arm, arms), sum_variants(v, ls, ts, arms), expected), es)
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        refuse(v, string_append(str_lit("tagcase of a "), string_append(show_ty(s, t), str_lit(", no datatype"))))
                    }
                }
            }
        }
    }
}

/// `(product (l e) ...)`: each field checked against the type expected
/// of it, if a product of those labels is expected, else found.
pub fn product_form(v: &'static Cv, s: &'static St, fields: Sexps, expected: Tys) -> &'static Res {
    let fs = map(&items, fields);
    let ls = map(lambda1(move |f: Sexps| {
        label_of(car(f))
    }), fs);
    let want = if null_p(expected) {
        nil()
    } else {
        let tagcase_ = walk(s, car(expected));
        match *tagcase_ {
            Ty::TyShape(p, ms, us) => {
                if (p && strings_eq_p(ls, ms)) {
                    us
                } else {
                    nil()
                }
            }
            _ => {
                let other = tagcase_;
                nil()
            }
        }
    };
    if any_p(lambda1(move |f: Sexps| {
        (not(i64_eq(size(f), 2i64)) || string_eq_p(label_of(car(f)), str_lit("")))
    }), fs) {
        refuse(v, str_lit("a product's fields are each (label value)"))
    } else if repeated_p(ls) {
        refuse(v, str_lit("a label appears twice in a product"))
    } else {
        let tagcase_ = product_values(v, s, map(&second, fs), want);
        match *tagcase_ {
            Res::Res(t, es, s) => {
                let tagcase_ = t;
                match *tagcase_ {
                    Ty::TyShape(p, ms, us) => {
                        let r = res(ty_shape(true, ls, us), es, s);
                        if null_p(expected) {
                            r
                        } else {
                            let tagcase_ = r;
                            match *tagcase_ {
                                Res::Res(t2, es2, s2) => {
                                    res(t2, es2, fits(v, s2, t2, car(expected)))
                                }
                            }
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        refuse(v, str_lit("a product"))
                    }
                }
            }
        }
    }
}

/// Values, each checked against its type in `want` if there is one;
/// their types as a sum of no tags, a carrier.
pub fn product_values(v: &'static Cv, s: &'static St, es: Sexps, want: Tys) -> &'static Res {
    if null_p(es) {
        res(ty_shape(true, nil(), nil()), nil(), s)
    } else {
        let tagcase_ = if null_p(want) {
            synth(v, s, car(es))
        } else {
            check(v, s, car(es), car(want))
        };
        match *tagcase_ {
            Res::Res(t, es0, s) => {
                let tagcase_ = product_values(v, s, cdr(es), if null_p(want) {
                    nil()
                } else {
                    cdr(want)
                });
                match *tagcase_ {
                    Res::Res(rest, es1, s) => {
                        let tagcase_ = rest;
                        match *tagcase_ {
                            Ty::TyShape(p, ls, ts) => {
                                res(ty_shape(true, ls, cons(t, ts)), effs_union(es0, es1), s)
                            }
                            _ => {
                                let other = tagcase_;
                                res(rest, es1, s)
                            }
                        }
                    }
                }
            }
        }
    }
}

/// `(sum tag e)`, where a sum with that tag is expected: its type known
/// whole, which the emitter is told, for Rust's sake.
pub fn sum_form(v: &'static Cv, s: &'static St, xs: Sexps, expected: &'static Ty) -> &'static Res {
    let tagcase_ = walk(s, expected);
    match *tagcase_ {
        Ty::TyShape(p, ls, ts) => {
            let tag = label_of(car(xs));
            if (p || not(string_member_p(tag, ls)) || not(i64_eq(size(xs), 2i64))) {
                refuse(v, string_append(str_lit("a sum tagged "), string_append(tag, string_append(str_lit(", where a "), string_append(show_ty(s, expected), str_lit(" is expected"))))))
            } else {
                let tagcase_ = check(v, s, second(xs), member_type(tag, ls, ts));
                match *tagcase_ {
                    Res::Res(t, es, s) => {
                        res(expected, es, note_fact(s, cv_file(v), cv_pos(v), string_append(str_lit("sum-type "), show_sexp(ty_sexp(v, s, zonk(s, expected))))))
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            refuse(v, str_lit("a sum whose type is not known here: write it, (the (sumof ...) (sum ...))"))
        }
    }
}

/// Branches of one type: the first found, if none is expected, and the
/// rest checked against it.
pub fn arms(v: &'static Cv, s: &'static St, branches: Sexps, expected: Tys) -> &'static Res {
    let tagcase_ = body(v, s, cons(car(branches), nil()), expected);
    match *tagcase_ {
        Res::Res(t, es, s) => {
            if null_p(cdr(branches)) {
                res(t, es, s)
            } else {
                let tagcase_ = arms(v, s, cdr(branches), next_expected(s, t, expected));
                match *tagcase_ {
                    Res::Res(t2, es2, s) => {
                        res(joined(s, t, t2, expected), effs_union(es, es2), join_state(v, s, t, t2, expected))
                    }
                }
            }
        }
    }
}

pub fn cond_clauses(v: &'static Cv, s: &'static St, clauses: Sexps, expected: Tys) -> &'static Res {
    let clause = items(car(clauses));
    if sym_is_p(car(clause), str_lit("else")) {
        if null_p(cdr(clauses)) {
            body(v, s, cdr(clause), expected)
        } else {
            refuse(v, str_lit("a cond's else is its last clause"))
        }
    } else {
        if null_p(cdr(clauses)) {
            refuse(v, str_lit("a cond needs an else: FX has no unspecified value"))
        } else {
            let tagcase_ = check(v, s, car(clause), ty_bool());
            match *tagcase_ {
                Res::Res(t0, es0, s) => {
                    let tagcase_ = body(v, s, cdr(clause), expected);
                    match *tagcase_ {
                        Res::Res(t, es, s) => {
                            let tagcase_ = cond_clauses(v, s, cdr(clauses), next_expected(s, t, expected));
                            match *tagcase_ {
                                Res::Res(t2, es2, s) => {
                                    res(joined(s, t, t2, expected), effs_union(es0, effs_union(es, es2)), join_state(v, s, t, t2, expected))
                                }
                            }
                        }
                    }
                }
            }
        }
    }
}

pub fn case_arms(v: &'static Cv, s: &'static St, kind: Str, cases: Sexps, expected: Tys) -> &'static Res {
    let arm = items(car(cases));
    if sym_is_p(car(arm), str_lit("else")) {
        if null_p(cdr(cases)) {
            body(v, s, cdr(arm), expected)
        } else {
            refuse(v, str_lit("a case's else is its last arm"))
        }
    } else if null_p(cdr(cases)) {
        refuse(v, str_lit("a case needs an else: FX has no unspecified value"))
    } else if null_p(items(car(arm))) {
        refuse(v, str_lit("a case clause has at least one datum"))
    } else if not(case_data_p(kind, items(car(arm)))) {
        refuse(v, string_append(str_lit("a case on a "), string_append(kind, str_lit("'s data are literals of its type"))))
    } else if repeated_p(map(&datum_key, concat(map(lambda1(move |c: &'static Sexp| {
        if sym_is_p(car(items(c)), str_lit("else")) {
            nil()
        } else {
            items(car(items(c)))
        }
    }), cases)))) {
        refuse(v, str_lit("a datum appears twice in this case"))
    } else {
        let tagcase_ = body(v, case_data(v, s, kind, items(car(arm))), cdr(arm), expected);
        match *tagcase_ {
            Res::Res(t, es, s) => {
                let tagcase_ = case_arms(v, s, kind, cdr(cases), next_expected(s, t, expected));
                match *tagcase_ {
                    Res::Res(t2, es2, s) => {
                        res(joined(s, t, t2, expected), effs_union(es, es2), join_state(v, s, t, t2, expected))
                    }
                }
            }
        }
    }
}

/// A case's data, an int's checked as ints, so that the emitter writes
/// them as ints.
pub fn case_data(v: &'static Cv, s: &'static St, kind: Str, xs: Sexps) -> &'static St {
    if (null_p(xs) || not(string_eq_p(kind, str_lit("int")))) {
        s
    } else {
        let tagcase_ = check(v, s, car(xs), ty_int());
        match *tagcase_ {
            Res::Res(t, es, s) => {
                case_data(v, s, kind, cdr(xs))
            }
        }
    }
}

/// A tagcase's arms; `vs` are the variants no arm has taken yet.
pub fn tag_arms(v: &'static Cv, s: &'static St, whole: &'static Ty, tagged: Sexps, vs: Variants, expected: Tys) -> &'static Res {
    if null_p(tagged) {
        if null_p(vs) {
            res(if null_p(expected) {
                ty_void()
            } else {
                car(expected)
            }, nil(), s)
        } else {
            refuse(v, string_append(str_lit("a tagcase of a "), string_append(show_ty(s, whole), str_lit(" with no else, and no arm for each tag"))))
        }
    } else {
        let arm = items(car(tagged));
        let tag = name_of(v, car(arm));
        if string_eq_p(tag, str_lit("else")) {
            if null_p(cdr(tagged)) {
                body(with_binds(v, cons(local(v, name_of(v, second(arm)), whole), nil())), s, cdr(cdr(arm)), expected)
            } else {
                refuse(v, str_lit("a tagcase's else is its last arm"))
            }
        } else {
            let fields = variant_fields(v, show_ty(s, whole), tag, vs);
            let names = items(second(arm));
            if not(i64_eq(size(names), size(fields))) {
                refuse(v, string_append(str_lit("the arm for "), string_append(tag, str_lit(" names the wrong number of fields"))))
            } else {
                let tagcase_ = body(with_binds(v, bind_fields(v, names, fields)), s, cdr(cdr(arm)), expected);
                match *tagcase_ {
                    Res::Res(t, es, s) => {
                        let tagcase_ = tag_arms(v, s, whole, cdr(tagged), without_tag(tag, vs), next_expected(s, t, expected));
                        match *tagcase_ {
                            Res::Res(t2, es2, s) => {
                                res(joined(s, t, t2, expected), effs_union(es, es2), join_state(v, s, t, t2, expected))
                            }
                        }
                    }
                }
            }
        }
    }
}

/// A `let`'s or `let*`'s bindings, then its body. `bound`: those made
/// so far, which a `let*`'s next binding sees and a `let`'s does not.
pub fn let_values(v: &'static Cv, s: &'static St, bindings: Sexps, forms: Sexps, expected: Tys, bound: Binds, sequential: bool) -> &'static Res {
    if null_p(bindings) {
        body(with_binds(v, bound), s, forms, expected)
    } else {
        let b = items(car(bindings));
        let sees = if sequential {
            with_binds(v, bound)
        } else {
            v
        };
        let tagcase_ = synth(sees, s, second(b));
        match *tagcase_ {
            Res::Res(t, es, s) => {
                with_effs(let_values(v, s, cdr(bindings), forms, expected, cons(local(v, name_of(v, car(b)), t), bound), sequential), es)
            }
        }
    }
}

/// `(letrec ((f T lambda) ...) body ...)`: each procedure's type written,
/// every one in scope in each lambda and in the body. A group whose every
/// run ends is bound as `ends`, its calls no `spin`; else as locals.
pub fn letrec_form(v: &'static Cv, s: &'static St, bindings: Sexps, forms: Sexps, expected: Tys) -> &'static Res {
    let ends = terminates_p(v, map(lambda1(move |b: &'static Sexp| {
        name_of(v, car(items(b)))
    }), bindings), map(lambda1(move |b: &'static Sexp| {
        parse_type(v, cv_tvars(v), second(items(b)))
    }), bindings), map(lambda1(move |b: &'static Sexp| {
        third(items(b))
    }), bindings));
    let w = with_binds(v, map(lambda1(move |b: &'static Sexp| {
        let ys = items(b);
        bind(name_of(v, car(ys)), scheme(nil(), parse_type(v, cv_tvars(v), second(ys))), if ends {
            str_lit("ends")
        } else {
            str_lit("rec")
        })
    }), bindings));
    let tagcase_ = letrec_lambdas(w, s, bindings);
    match *tagcase_ {
        Res::Res(u, es, s) => {
            body(w, s, forms, expected)
        }
    }
}

/// `(letregion r body ...)`: a region for the body's types, its data the
/// heap's. What the body does to it is masked, and the value may not
/// mention it, as in FX-26. A region named already is refused, so that
/// masking, by name, masks nothing else.
pub fn letregion_form(v: &'static Cv, s: &'static St, r: Str, forms: Sexps, expected: Tys) -> &'static Res {
    let name = string_append(str_lit("'"), r);
    if string_member_p(name, cv_tvars(v)) {
        refuse(v, string_append(str_lit("a letregion of a region named already: "), r))
    } else {
        let tagcase_ = found_then_fitted(v, body(with_tvars(v, cons(name, nil())), s, forms, nil()), expected);
        match *tagcase_ {
            Res::Res(t, es, s) => {
                if mentions_p(s, t, name) {
                    refuse(v, string_append(str_lit("a letregion whose value's type mentions its region "), r))
                } else {
                    res(t, masked(es, name), s)
                }
            }
        }
    }
}

pub fn letrec_lambdas(v: &'static Cv, s: &'static St, bindings: Sexps) -> &'static Res {
    if null_p(bindings) {
        res(ty_unit(), nil(), s)
    } else {
        let ys = items(car(bindings));
        if not(head_is_p(third(ys), str_lit("lambda"))) {
            refuse(v, str_lit("a letrec binds only lambdas"))
        } else {
            let tagcase_ = check(v, s, third(ys), parse_type(v, cv_tvars(v), second(ys)));
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    letrec_lambdas(v, s, cdr(bindings))
                }
            }
        }
    }
}

/// A lambda with nothing expected: its parameters' types written.
pub fn synth_lambda(v: &'static Cv, s: &'static St, params: Sexps, forms: Sexps) -> &'static Res {
    let types = map(lambda1(move |p: &'static Sexp| {
        let tagcase_ = p;
        match *tagcase_ {
            Sexp::Lst(pt, src_file, src_line, src_pos) => {
                parse_type(v, cv_tvars(v), second(pt))
            }
            _ => {
                let other = tagcase_;
                refuse(v, string_append(str_lit("a lambda with nothing expected needs its parameters' types: "), show_sexp(other)))
            }
        }
    }), params);
    if any_p(lambda1(move |p: &'static Ty| {
        not(null_p(module_spec(v, p)))
    }), types) {
        refuse(v, str_lit("a module parameter is a top-level procedure's (C24)"))
    } else {
        let tagcase_ = body(with_binds(v, bind_params(v, params, types)), s, forms, nil());
        match *tagcase_ {
            Res::Res(r, es, s) => {
                res(ty_proc(es, types, r), nil(), if escapes_p(es) {
                    note_fact(s, cv_file(v), cv_pos(v), str_lit("fallible"))
                } else {
                    s
                })
            }
        }
    }
}

pub fn check_lambda(v: &'static Cv, s: &'static St, params: Sexps, forms: Sexps, expected: &'static Ty) -> &'static Res {
    let tagcase_ = expected;
    match *tagcase_ {
        Ty::TyProc(ees, eps, er) => {
            if not(i64_eq(size(params), size(eps))) {
                refuse(v, str_lit("a lambda of the wrong number of parameters"))
            } else {
                let s = check_written_params(v, s, params, eps);
                if (not(null_p(module_spec(v, walk(s, er)))) || (any_p(lambda1(move |p: &'static Ty| {
                    not(null_p(module_spec(v, walk(s, p))))
                }), eps) && not(top_lambda_p(v)))) {
                    refuse(v, str_lit("a module parameter is a top-level procedure's, and no procedure gives a module back (C24)"))
                } else {
                    let tagcase_ = body(with_binds(v, cons(bind(str_lit("%toplambda"), scheme(nil(), ty_unit()), str_lit("no")), bind_params(v, params, eps))), s, forms, cons(er, nil()));
                    match *tagcase_ {
                        Res::Res(r, es, s) => {
                            if not(null_p(fit_effs(s, es, ees))) {
                                let s = car(fit_effs(s, es, ees));
                                let s = if any_p(lambda1(move |p: &'static Ty| {
                                    (has_meta_p(s, p) || has_var_p(s, p))
                                }), eps) {
                                    s
                                } else {
                                    note_fact(s, cv_file(v), cv_pos(v), string_append(str_lit("param-types "), show_sexp(lst(map(lambda1(move |p: &'static Ty| {
                                        ty_sexp(v, s, zonk(s, p))
                                    }), eps), str_lit(""), 0i64, 0i64))))
                                };
                                res(expected, nil(), if escapes_p(ees) {
                                    note_fact(s, cv_file(v), cv_pos(v), str_lit("fallible"))
                                } else {
                                    s
                                })
                            } else {
                                refuse(v, string_append(str_lit("a lambda whose effect "), string_append(show_effs(es), string_append(str_lit(" is not within "), show_effs(ees)))))
                            }
                        }
                    }
                }
            }
        }
        _ => {
            let other = tagcase_;
            refuse(v, str_lit("a lambda where no procedure is expected"))
        }
    }
}

/// A lambda's body's effect, the body checked against the type `t`'s
/// parameters and result, but not its effect: what `define*` finds.
pub fn lambda_effects(v: &'static Cv, s: &'static St, params: Sexps, forms: Sexps, t: &'static Ty) -> &'static Res {
    let tagcase_ = t;
    match *tagcase_ {
        Ty::TyProc(ees, eps, er) => {
            if not(i64_eq(size(params), size(eps))) {
                refuse(v, str_lit("a lambda of the wrong number of parameters"))
            } else {
                body(with_binds(v, bind_params(v, params, eps)), check_written_params(v, s, params, eps), forms, cons(er, nil()))
            }
        }
        _ => {
            let other = tagcase_;
            refuse(v, str_lit("a lambda where no procedure is expected"))
        }
    }
}

/// A parameter written `(x T)` must be of the type expected. One written
/// `x` must have its type known already, from the arguments before the
/// lambda: rustc, which checks a call's arguments in order, finds a
/// closure's parameter types no other way.
pub fn check_written_params(mut v: &'static Cv, mut s: &'static St, mut params: Sexps, mut types: Tys) -> &'static St {
    loop {
        if null_p(params) {
            return s;
        } else {
            (s, params, types) = ({
                let tagcase_ = car(params);
                match *tagcase_ {
                    Sexp::Lst(pt, src_file, src_line, src_pos) => {
                        fits(v, s, car(types), parse_type(v, cv_tvars(v), second(pt)))
                    }
                    _ => {
                        let other = tagcase_;
                        if has_meta_p(s, car(types)) {
                            refuse(v, string_append(str_lit("the type of the lambda's parameter "), string_append(show_sexp(other), str_lit(" is not known from the arguments before it: write it as (x T)"))))
                        } else {
                            s
                        }
                    }
                }
            }, cdr(params), cdr(types));
            continue;
        }
    }
}

/// A call of a name: a procedure in this group is `spin`, one that is a
/// local's value is a call of a procedure not known, so `spin` too.
pub fn synth_call(v: &'static Cv, s: &'static St, h: Str, args: Sexps, expected: Tys) -> &'static Res {
    let found = find_bind(h, cv_binds(v));
    if keyword_p(h) {
        refuse(v, string_append(str_lit("("), string_append(h, str_lit(" ...) is FX-26's form, which KFX does not have, or a call of a local named by that keyword"))))
    } else if (null_p(found) && string_eq_p(h, str_lit("abort-current-continuation"))) {
        abort_call(v, s, args)
    } else if (null_p(found) && string_eq_p(h, str_lit("make-continuation-prompt-tag"))) {
        make_tag_call(v, s, args, expected)
    } else if (null_p(found) && (string_eq_p(h, str_lit("call-with-composable-continuation")) || string_eq_p(h, str_lit("call-with-current-continuation")) || string_eq_p(h, str_lit("call/cc")))) {
        refuse(v, string_append(h, str_lit(" keeps a continuation, a comefrom, which KFX does not have: Rust has no frames to resume (docs/research/escapes.md)")))
    } else if null_p(found) {
        refuse(v, string_append(str_lit("nothing is named "), h))
    } else if (nat_op_p(h) && prim_p(car(found)) && i64_eq(size(args), 2i64) && nat_args_p(v, s, args)) {
        let tagcase_ = call_args(v, s, args, cons(ty_nat(), cons(ty_nat(), nil())), nil());
        match *tagcase_ {
            Res::Res(u, es, s) => {
                res(ty_nat(), es, if null_p(expected) {
                    s
                } else {
                    fits(v, s, ty_nat(), car(expected))
                })
            }
        }
    } else {
        let tagcase_ = car(found);
        match *tagcase_ {
            Bind::Bind(n, sc, r#where) => {
                let tagcase_ = instantiate(s, sc);
                match *tagcase_ {
                    Inst::Inst(t, s, regions) => {
                        knot_free_call(v, synth_call_of(v, s, res(t, nil(), s), args, regions, expected, effs_union(if string_eq_p(r#where, str_lit("global")) {
                            cons(string_append(str_lit("g:"), h), nil())
                        } else {
                            nil()
                        }, if (string_eq_p(r#where, str_lit("rec")) || (string_eq_p(r#where, str_lit("local")) && self_applicable_p(v, s, t)) || (string_member_p(h, cv_group(v)) && (string_eq_p(r#where, str_lit("global")) || string_eq_p(r#where, str_lit("item"))))) {
                            cons(str_lit("spin"), nil())
                        } else {
                            nil()
                        })))
                    }
                }
            }
        }
    }
}

/// Whether each argument is a `nat`: a literal not negative, or what
/// its type is found to be. The finding is a test, its state dropped.
pub fn nat_args_p(v: &'static Cv, s: &'static St, args: Sexps) -> bool {
    (null_p(args) || ({
        let tagcase_ = car(args);
        match *tagcase_ {
            Sexp::Num(k, f, p) => {
                (not(i64_lt(k, 0i64)) && not(i64_gt(k, 1152921504606846975i64)))
            }
            Sexp::Big(text, f, p) => {
                false
            }
            _ => {
                let other = tagcase_;
                let tagcase_ = synth(v, s, other);
                match *tagcase_ {
                    Res::Res(t, es, s2) => {
                        nat_p(s2, t)
                    }
                }
            }
        }
    } && nat_args_p(v, s, cdr(args))))
}

/// `(abort-current-continuation tag v)`: to the innermost prompt of
/// `tag`, with `v`; a `goto` on the tag's region, and of type `void`.
pub fn abort_call(v: &'static Cv, s: &'static St, args: Sexps) -> &'static Res {
    if not(i64_eq(size(args), 2i64)) {
        refuse(v, str_lit("abort-current-continuation takes a tag and a value"))
    } else {
        let tagcase_ = synth(v, s, car(args));
        match *tagcase_ {
            Res::Res(t, es0, s) => {
                let tagcase_ = walk(s, t);
                match *tagcase_ {
                    Ty::TyTag(a, h, d, r) => {
                        let tagcase_ = check(v, s, second(args), h);
                        match *tagcase_ {
                            Res::Res(u, es1, s) => {
                                res(ty_void(), effs_union(cons(string_append(str_lit("goto:"), region_string(s, r)), nil()), effs_union(es0, es1)), s)
                            }
                        }
                    }
                    _ => {
                        let other = tagcase_;
                        refuse(v, string_append(str_lit("an abort to a "), string_append(show_ty(s, t), str_lit(", no prompt-tag"))))
                    }
                }
            }
        }
    }
}

/// `(make-continuation-prompt-tag)`: its type, said where it is made.
pub fn make_tag_call(v: &'static Cv, s: &'static St, args: Sexps, expected: Tys) -> &'static Res {
    if not(null_p(args)) {
        refuse(v, str_lit("make-continuation-prompt-tag takes nothing"))
    } else if null_p(expected) {
        refuse(v, str_lit("a prompt tag whose type nothing says: write (the (prompt-tag A H D R) (make-continuation-prompt-tag))"))
    } else {
        let tagcase_ = walk(s, car(expected));
        match *tagcase_ {
            Ty::TyTag(a, h, d, r) => {
                res(car(expected), cons(string_append(str_lit("alloc:"), region_string(s, r)), nil()), s)
            }
            _ => {
                let other = tagcase_;
                refuse(v, str_lit("a prompt tag where none is expected"))
            }
        }
    }
}

/// `(prompt tag body handler)`, as FX-26 has it: the body of the tag's
/// answer type, its effect, but for control on the tag's region, within
/// the tag's bound; an abort to the tag runs the handler. The prompt
/// removes the `goto` on the region when the body can reach no other tag
/// there: when nothing it names but the tag has a type that mentions the
/// region (every name, bound in it or not: stricter than FX-26's free
/// variables, never laxer).
pub fn prompt_form(v: &'static Cv, s: &'static St, xs: Sexps, expected: Tys) -> &'static Res {
    let tagcase_ = synth(v, s, car(xs));
    match *tagcase_ {
        Res::Res(tt, es0, s) => {
            let tagcase_ = walk(s, tt);
            match *tagcase_ {
                Ty::TyTag(a, h, d, r) => {
                    let rn = region_string(s, r);
                    let tagcase_ = check(v, s, second(xs), a);
                    match *tagcase_ {
                        Res::Res(u, es1, s) => {
                            if not(effs_within_p(masked_goto(es1, rn), d)) {
                                refuse(v, string_append(str_lit("the tag allows its delimited computations "), string_append(show_effs(d), string_append(str_lit(", and this body also has "), show_effs(masked_goto(es1, rn))))))
                            } else {
                                let tagcase_ = handler_of(v, s, third(xs), h, a);
                                match *tagcase_ {
                                    Res::Res(u2, es2, s) => {
                                        let delimits = not(reaches_p(v, s, second(xs), car(xs), rn));
                                        let s = if delimits {
                                            note_fact(s, cv_file(v), cv_pos(v), str_lit("delimits"))
                                        } else {
                                            s
                                        };
                                        let s = if (delimits && not(escapes_p(masked_goto(es1, rn)))) {
                                            note_fact(s, cv_file(v), cv_pos(v), str_lit("contains"))
                                        } else {
                                            s
                                        };
                                        let s = if null_p(expected) {
                                            s
                                        } else {
                                            fits(v, s, a, car(expected))
                                        };
                                        res(a, effs_union(es0, effs_union(es2, if delimits {
                                            masked_goto(es1, rn)
                                        } else {
                                            es1
                                        })), s)
                                    }
                                }
                            }
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    refuse(v, string_append(str_lit("a prompt of a "), string_append(show_ty(s, tt), str_lit(", no prompt-tag"))))
                }
            }
        }
    }
}

/// A prompt's handler, a lambda from the payload to the answer: its
/// body's effect is the prompt's, since the prompt calls it. A handler
/// that may abort, KFX has not yet.
pub fn handler_of(v: &'static Cv, s: &'static St, e: &'static Sexp, h: &'static Ty, a: &'static Ty) -> &'static Res {
    if not(head_is_p(e, str_lit("lambda"))) {
        refuse(v, str_lit("a prompt's handler is a lambda, in KFX"))
    } else {
        let lam = items(e);
        let tagcase_ = lambda_effects(v, s, items(second(lam)), cdr(cdr(lam)), ty_proc(nil(), cons(h, nil()), a));
        match *tagcase_ {
            Res::Res(u, es, s) => {
                if escapes_p(es) {
                    refuse(v, str_lit("a prompt's handler that may abort, which KFX has not yet"))
                } else {
                    res(a, es, s)
                }
            }
        }
    }
}

/// A call of the procedure `callee` is: its result fitted to the type
/// `expected`, if one is, then its arguments checked against its
/// parameters, in order (a `list` given for a parameter whose type is an
/// instance's found by itself, as FX-26 finds it); its effect, the callee's latent effect, the
/// arguments' and `more`. In order, not lambdas last as FX-26 does,
/// since rustc finds a closure's parameter types only from what comes
/// before it: see `check-written-params`.
pub fn synth_call_of(v: &'static Cv, s: &'static St, callee: &'static Res, args: Sexps, regions: List<i64>, expected: Tys, more: Strings) -> &'static Res {
    let tagcase_ = callee;
    match *tagcase_ {
        Res::Res(t, es0, s) => {
            let tagcase_ = walk(s, t);
            match *tagcase_ {
                Ty::TyProc(latent, ps, r) => {
                    if not(i64_eq(size(ps), size(args))) {
                        refuse(v, string_append(str_lit("a call of the wrong number of arguments: "), show_sexps(args)))
                    } else {
                        let tagcase_ = {
                            let s1 = if null_p(expected) {
                                s
                            } else {
                                fits(v, s, r, car(expected))
                            };
                            call_args(v, s1, args, ps, fixed_by(s, s1, concat(map(&metas_of, ps))))
                        };
                        match *tagcase_ {
                            Res::Res(u, es1, s0) => {
                                let s = lifted_args(v, s0, args, ps, 0i64);
                                let tagcase_ = name_regions(v, s, latent, regions);
                                match *tagcase_ {
                                    Res::Res(u, named, s) => {
                                        res(r, effs_union(named, effs_union(more, effs_union(es0, es1))), if escapes_p(named) {
                                            note_fact(s, cv_file(v), cv_pos(v), str_lit("fallible-call"))
                                        } else {
                                            s
                                        })
                                    }
                                }
                            }
                        }
                    }
                }
                _ => {
                    let other = tagcase_;
                    refuse(v, string_append(str_lit("a call of a "), string_append(show_ty(s, t), str_lit(", no procedure"))))
                }
            }
        }
    }
}

/// The arguments, in order, but for `nil` given for a parameter that is
/// an inference variable, which is heard after the rest, as FX-26 hears
/// it. A literal is not: FX-26 makes it an `int` where it stands.
pub fn call_args(v: &'static Cv, s: &'static St, args: Sexps, ps: Tys, fixed: I64s) -> &'static Res {
    let tagcase_ = call_args_pass(v, s, args, ps, false, fixed);
    match *tagcase_ {
        Res::Res(u, es, s) => {
            with_effs(call_args_pass(v, s, args, ps, true, fixed), es)
        }
    }
}

/// A module given for a module parameter: one defined at the top level, by
/// its name, read as a global is.
pub fn module_argument(v: &'static Cv, s: &'static St, arg: &'static Sexp, t: &'static Ty) -> &'static Res {
    let name = {
        let tagcase_ = arg;
        match *tagcase_ {
            Sexp::Sym(n) => {
                n
            }
            _ => {
                let other = tagcase_;
                str_lit("")
            }
        }
    };
    if (string_eq_p(name, str_lit("")) || null_p(find_bind(name, cv_binds(v))) || not({
        let tagcase_ = car(find_bind(name, cv_binds(v)));
        match *tagcase_ {
            Bind::Bind(n, sc, r#where) => {
                string_eq_p(r#where, str_lit("module"))
            }
        }
    })) {
        refuse(v, str_lit("KFX's module argument is a module defined at the top level, by its name"))
    } else {
        res(t, cons(string_append(str_lit("g:"), name), nil()), conforms(v, s, name, {
            let tagcase_ = t;
            match *tagcase_ {
                Ty::TyData(d, args) => {
                    after_prefix(d, str_lit("%module "))
                }
                _ => {
                    let other = tagcase_;
                    str_lit("")
                }
            }
        }, car(module_spec(v, t))))
    }
}

/// The arguments `deferred?` says are `later`'s.
pub fn call_args_pass(mut v: &'static Cv, mut s: &'static St, mut args: Sexps, mut ps: Tys, mut later: bool, mut fixed: I64s) -> &'static Res {
    loop {
        if null_p(args) {
            return res(ty_unit(), nil(), s);
        } else if eqv_bool_p(deferred_p(car(args), car(ps)), later) {
            let tagcase_ = if not(null_p(module_spec(v, walk(s, car(ps))))) {
                module_argument(v, s, car(args), walk(s, car(ps)))
            } else if (head_is_p(car(args), str_lit("list")) && has_meta_p(s, car(ps))) {
                // A `list` for a parameter whose type is not known whole yet:
                // found by itself, at a fresh region, as FX-26 finds it.
                check_by_synth(v, s, car(args), car(ps))
            } else {
                check(v, s, car(args), car(ps))
            };
            match *tagcase_ {
                Res::Res(t, es, s) => {
                    return with_effs(call_args_pass(v, s, cdr(args), cdr(ps), later, fixed), es);
                }
            }
        } else {
            (args, ps) = (cdr(args), cdr(ps));
            continue;
        }
    }
}

